class Solution {
public:
    int minNumber(std::vector<int>& nums1, std::vector<int>& nums2) {
        std::unordered_set<int> s(nums1.begin(), nums1.end());
        int common_min = 10;
        for (int x : nums2) {
            if (s.count(x)) common_min = std::min(common_min, x);
        }
        if (common_min < 10) return common_min;
        int m1 = *std::min_element(nums1.begin(), nums1.end());
        int m2 = *std::min_element(nums2.begin(), nums2.end());
        return std::min(m1 * 10 + m2, m2 * 10 + m1);
    }
};

class Solution {
    public int minNumber(int[] nums1, int[] nums2) {
        java.util.Set<Integer> s = new java.util.HashSet<>();
        int m1 = 10, m2 = 10;
        for (int x : nums1) {
            s.add(x);
            m1 = Math.min(m1, x);
        }
        int commonMin = 10;
        for (int x : nums2) {
            if (s.contains(x)) commonMin = Math.min(commonMin, x);
            m2 = Math.min(m2, x);
        }
        if (commonMin < 10) return commonMin;
        return Math.min(m1 * 10 + m2, m2 * 10 + m1);
    }
}

var minNumber = function(nums1, nums2) {
    const s = new Set(nums1);
    let commonMin = 10;
    for (const x of nums2) {
        if (s.has(x)) commonMin = Math.min(commonMin, x);
    }
    if (commonMin < 10) return commonMin;
    const m1 = Math.min(...nums1);
    const m2 = Math.min(...nums2);
    return Math.min(m1 * 10 + m2, m2 * 10 + m1);
};
